import type { FilterDataStructure } from 'models/Filters';

import { FilterConfig } from '../types';

const makeWatchTowerFilterConfig = (
  key: string,
  order: number,
  displayName: string,
  parentKey: string,
  dependentKeys: string[] = [],
  parentAware = true,
  description?: string,
): FilterConfig => ({
  key,
  order,
  isCommon: false,
  parentKey,
  calculator: (filterData: FilterDataStructure) =>
    (
      filterData as Record<
        string,
        { default?: { value?: string | null } | null }
      >
    )[key]?.default?.value ?? null,
  validator: (filterData: FilterDataStructure, value) => {
    const options =
      (filterData as Record<string, { values?: { value: unknown }[] }>)[key]
        ?.values || [];
    return options.some((opt) => opt.value === value);
  },
  ...(parentAware
    ? {
        contextualValidator: (dataFilters, parentValue, childValue) => {
          const dimension = (
            dataFilters as Record<
              string,
              {
                values?: Array<{ value: unknown }>;
                values_by_parent?: Record<string, Array<{ value: unknown }>>;
              }
            >
          )[key];
          if (!parentValue) return false;
          return (
            dimension?.values_by_parent?.[String(parentValue)]?.some(
              (option) => option.value === childValue,
            ) ?? false
          );
        },
        dependentDefaultCascadingCalculator: (
          filterData: FilterDataStructure,
          currentValues,
        ) => {
          const current = currentValues[key];
          const parent = currentValues[parentKey];
          if (!current || !parent) return null;
          const dimension = (
            filterData as Record<
              string,
              {
                values?: Array<{ value: unknown }>;
                values_by_parent?: Record<string, Array<{ value: unknown }>>;
              }
            >
          )[key];
          return dimension?.values_by_parent?.[String(parent)]?.some(
            (option) => option.value === current,
          )
            ? current
            : null;
        },
      }
    : {
        dependentDefaultCascadingCalculator: () => null,
      }),
  dependencies: dependentKeys,
  metadata: {
    displayName,
    description:
      description ?? `WatchTower driver decomposition level: ${displayName}`,
  },
});

export const watchTowerDriverFilterConfig = makeWatchTowerFilterConfig(
  'driver',
  53,
  'Driver',
  'watch_tower_brand',
  [
    'vehicle_level_1',
    'vehicle_level_2',
    'vehicle_level_3',
    'vehicle_level_4',
    'vehicle_level_5',
  ],
  false,
  'WatchTower decomposition driver filter',
);

export const watchTowerVehicleLevel1FilterConfig = makeWatchTowerFilterConfig(
  'vehicle_level_1',
  54,
  'Vehicle 1',
  'driver',
  ['vehicle_level_2', 'vehicle_level_3', 'vehicle_level_4', 'vehicle_level_5'],
);

export const watchTowerVehicleLevel2FilterConfig = makeWatchTowerFilterConfig(
  'vehicle_level_2',
  55,
  'Vehicle 2',
  'vehicle_level_1',
  ['vehicle_level_3', 'vehicle_level_4', 'vehicle_level_5'],
);

export const watchTowerVehicleLevel3FilterConfig = makeWatchTowerFilterConfig(
  'vehicle_level_3',
  56,
  'Vehicle 3',
  'vehicle_level_2',
  ['vehicle_level_4', 'vehicle_level_5'],
);

export const watchTowerVehicleLevel4FilterConfig = makeWatchTowerFilterConfig(
  'vehicle_level_4',
  57,
  'Vehicle 4',
  'vehicle_level_3',
  ['vehicle_level_5'],
);

export const watchTowerVehicleLevel5FilterConfig = makeWatchTowerFilterConfig(
  'vehicle_level_5',
  58,
  'Vehicle 5',
  'vehicle_level_4',
);
